BEGIN
  SELECT payload INTO current_payload FROM app.owner_managed_datasets
    WHERE dataset_key = 'tech_footprint' FOR UPDATE;
  IF current_payload IS NULL THEN
    INSERT INTO app.owner_managed_datasets (dataset_key, payload, updated_by)
    VALUES ('tech_footprint', jsonb_build_object('version', 3, 'roadmap', '{"stages":[{"allocation":{"motion":5,"research":25,"robot":70},"date":"2026.09—2027.01","focus":{"zhCN":"以课程为主，先打牢现代 C++、Linux、STM32 和 ROS 2 硬件接入链路；暂时不追机械臂实机、VLA、3DGS 等高级功能","en":"Prioritize coursework and establish modern C++, Linux, STM32, and ROS 2 hardware integration foundations. Defer physical-arm deployment, VLA, 3DGS, and other advanced features."},"id":"c3ed611b-6b9c-462a-b2ae-ac03f32b33c1","milestone":{"zhCN":"Cyber AMR v0.5：STM32 → C++ Driver → ros2_control 完整打通","en":"Cyber AMR v0.5: complete STM32 → C++ Driver → ros2_control integration"},"position":0,"tasks":[{"goal":{"zhCN":"为后续所有机器人模块建立统一、可维护、可测试的工程规范。","en":"Establish consistent, maintainable, testable engineering practices for all subsequent robotics modules."},"id":"842ed1fc-57aa-4237-9a64-c5cbb3b7e658","position":0,"stack":["C++23","CMake","Linux","Git","GoogleTest","GDB"],"subtasks":[{"acceptance":{"zhCN":"","en":""},"id":"21170054-2879-4582-825b-e9b8c9ef5a76","position":0,"title":{"zhCN":"掌握 RAII、智能指针、移动语义、常用 STL 与错误处理","en":"Master RAII, smart pointers, move semantics, common STL facilities, and error handling"}},{"acceptance":{"zhCN":"","en":""},"id":"c31409a4-1e22-4ee2-a00a-f1ee8c6c4d38","position":1,"title":{"zhCN":"掌握线程、mutex、condition_variable、atomic 与常见并发问题","en":"Master threads, mutex, condition_variable, atomic, and common concurrency issues"}},{"acceptance":{"zhCN":"","en":""},"id":"a02c8ccc-d3d8-41c0-8511-9d25bca3326d","position":2,"title":{"zhCN":"掌握 target、库组织、依赖传递、install / export 与 find_package","en":"Master targets, library organization, transitive dependencies, install / export, and find_package"}},{"acceptance":{"zhCN":"","en":""},"id":"e0e84901-bd16-4ff7-b593-79bb0a68f069","position":3,"title":{"zhCN":"使用 GoogleTest 建立单元测试，并接入基础 CI","en":"Build GoogleTest unit tests and connect them to basic CI"}},{"acceptance":{"zhCN":"","en":""},"id":"02789ace-567d-4956-90d0-371682a491ab","position":4,"title":{"zhCN":"使用 GDB、Sanitizer、日志和 core dump 定位内存与并发问题","en":"Use GDB, sanitizers, logs, and core dumps to diagnose memory and concurrency problems"}}],"title":{"zhCN":"夯实现代 C++ 与 Linux 工程基础","en":"Strengthen modern C++ and Linux engineering foundations"},"track":"robot"},{"goal":{"zhCN":"形成稳定、安全、可测量的四电机控制固件。","en":"Build stable, safe, measurable four-motor control firmware."},"id":"af363cea-7d94-4128-a93e-12356e8150cc","position":1,"stack":["STM32","FreeRTOS","PID","Encoder","UART","CAN"],"subtasks":[{"acceptance":{"zhCN":"","en":""},"id":"8404e778-dbd2-43ec-b4a2-91d32eb3ed6d","position":0,"title":{"zhCN":"重新划分 FreeRTOS 任务、优先级、中断与控制周期","en":"Redesign FreeRTOS tasks, priorities, interrupts, and control periods"}},{"acceptance":{"zhCN":"","en":""},"id":"377c9a12-9d66-4c8d-85a0-d1621cb5e306","position":1,"title":{"zhCN":"完成编码器采集、轮速计算、单位和方向校验","en":"Implement encoder acquisition and wheel-speed calculation; verify units and directions"}},{"acceptance":{"zhCN":"保留阶跃、稳态误差、负载扰动和四轮一致性曲线","en":"Retain plots for step response, steady-state error, load disturbance, and wheel consistency"},"id":"31f6f3da-3ff6-4978-894c-62677ab99e66","position":2,"title":{"zhCN":"完成四电机速度 PID、输出限幅、Anti-windup 与基础前馈","en":"Implement four-motor speed PID, output limiting, anti-windup, and basic feedforward"}},{"acceptance":{"zhCN":"","en":""},"id":"fb2be513-2b84-4b0e-b504-dac0263afad4","position":3,"title":{"zhCN":"加入目标速度斜坡，避免速度指令突变带来的冲击","en":"Add target-speed ramps to prevent abrupt command changes"}},{"acceptance":{"zhCN":"","en":""},"id":"1136966b-f554-42a6-a211-12975a54531b","position":4,"title":{"zhCN":"完成通信超时停车、Watchdog、故障状态、急停和安全启动","en":"Implement communication-timeout stopping, watchdogs, fault states, emergency stops, and safe startup"}}],"title":{"zhCN":"重构 Cyber AMR 的 STM32 底层","en":"Refactor the STM32 firmware for Cyber AMR"},"track":"robot"},{"goal":{"zhCN":"让 STM32 与 Linux 共用同一套协议核心源码，并保持协议层与传输方式解耦。","en":"Share the same protocol core between STM32 and Linux while separating protocol logic from transport."},"id":"afd97fb0-045c-4c04-89e6-dbca8cb1c9fb","position":2,"stack":["C++23","CRC16","std::array","std::span"],"subtasks":[{"acceptance":{"zhCN":"","en":""},"id":"77d7f7f4-6f54-4e89-ae2e-d0ec353fcf87","position":0,"title":{"zhCN":"确定帧头、版本、长度、序号、CMD、Payload、CRC 和帧尾","en":"Define frame header, version, length, sequence number, CMD, payload, CRC, and trailer"}},{"acceptance":{"zhCN":"","en":""},"id":"55570b03-ea71-470e-8f83-13380b34ffcf","position":1,"title":{"zhCN":"实现无动态内存依赖的打包与解包接口","en":"Implement encoding and decoding interfaces without dynamic-memory dependencies"}},{"acceptance":{"zhCN":"","en":""},"id":"7dfd7cb8-3e45-49b5-a392-abb7cf7b71ea","position":2,"title":{"zhCN":"实现流式 Frame Parser，处理半帧、粘包、拆包、多帧和重新同步","en":"Implement a streaming frame parser for partial, concatenated, fragmented, and multiple frames, with resynchronization"}},{"acceptance":{"zhCN":"","en":""},"id":"120eb9b1-edab-44b9-bc76-b17a3c61b2a1","position":3,"title":{"zhCN":"确保协议核心不依赖 ROS 2、Boost.Asio、STM32 HAL 和 FreeRTOS","en":"Keep the protocol core independent of ROS 2, Boost.Asio, STM32 HAL, and FreeRTOS"}},{"acceptance":{"zhCN":"","en":""},"id":"02952fe7-cb6e-4baf-8c59-8b2a391f8a10","position":4,"title":{"zhCN":"为 CRC、Codec 和 Parser 建立边界与错误输入测试","en":"Test boundary conditions and malformed input for CRC, codec, and parser"}}],"title":{"zhCN":"建立跨平台 Robot Protocol","en":"Build a cross-platform Robot Protocol"},"track":"robot"},{"goal":{"zhCN":"把串口通信、设备状态和故障处理封装成不依赖 ROS 2 的设备驱动。","en":"Encapsulate serial communication, device state, and fault handling in a driver independent of ROS 2."},"id":"79f01e29-bac6-4364-b2cb-3dddee8e51cf","position":3,"stack":["C++23","Boost.Asio","GoogleTest"],"subtasks":[{"acceptance":{"zhCN":"","en":""},"id":"5a5e5039-bf21-44b8-b09a-cff677e4aeae","position":0,"title":{"zhCN":"完成 Boost.Asio 异步串口读写和线程模型","en":"Implement asynchronous serial I/O and threading with Boost.Asio"}},{"acceptance":{"zhCN":"","en":""},"id":"58311037-866e-4516-a70f-548577828ff6","position":1,"title":{"zhCN":"完成断连检测、自动重连、超时与 Heartbeat","en":"Implement disconnect detection, automatic reconnection, timeouts, and heartbeat"}},{"acceptance":{"zhCN":"","en":""},"id":"11e8f5a1-045f-4551-9b47-2a15697aebf8","position":2,"title":{"zhCN":"建立电机、编码器、IMU、故障和 Driver 状态接口","en":"Define interfaces for motor, encoder, IMU, fault, and driver state"}},{"acceptance":{"zhCN":"","en":""},"id":"4cffbf40-2ca7-4300-a27c-a72364b3c749","position":3,"title":{"zhCN":"建立 DriverConfig / SerialConfig，由上层负责参数来源","en":"Define DriverConfig / SerialConfig; let the caller determine configuration sources"}},{"acceptance":{"zhCN":"","en":""},"id":"6039f1ec-f287-4229-88bd-e508de38574d","position":4,"title":{"zhCN":"测试串口异常、错误帧、MCU 重启和 Driver 生命周期","en":"Test serial faults, malformed frames, MCU restarts, and the driver lifecycle"}}],"title":{"zhCN":"完成 Cyber AMR 的纯 C++ Linux Driver","en":"Complete the standalone C++ Linux driver for Cyber AMR"},"track":"robot"},{"goal":{"zhCN":"确定正式机器人系统的硬件控制入口，并让 ROS 2 只作为 Driver 的适配层。","en":"Establish the robot''s production hardware interface, using ROS 2 as an adapter around the driver."},"id":"0d02f5fd-a5ab-4b71-be41-f3b0035bc725","position":4,"stack":["ROS 2","ros2_control","pluginlib","TF2"],"subtasks":[{"acceptance":{"zhCN":"","en":""},"id":"77e6d191-333a-4b61-80b6-04ab4307b8c9","position":0,"title":{"zhCN":"实现 ros2_control SystemInterface、生命周期、read() 与 write()","en":"Implement ros2_control SystemInterface, lifecycle management, read(), and write()"}},{"acceptance":{"zhCN":"","en":""},"id":"caf45674-7f48-40e9-b42d-7307779cc718","position":1,"title":{"zhCN":"导出轮速 Command Interface 和关节 State Interface","en":"Export wheel-speed command interfaces and joint-state interfaces"}},{"acceptance":{"zhCN":"","en":""},"id":"ce054dad-3042-425e-b7e4-6a08b1c676b8","position":2,"title":{"zhCN":"接入 controller_manager、joint_state_broadcaster 与麦轮控制器","en":"Integrate controller_manager, joint_state_broadcaster, and the mecanum-wheel controller"}},{"acceptance":{"zh