2028.12","title":{"zhCN":"获得目标 Offer，学位论文完成 70%—80%","en":"Secure a target offer and complete 70–80% of the thesis"}},{"date":"2029.03","title":{"zhCN":"论文定稿与盲审阶段","en":"Finalize the thesis and enter blind review"}},{"date":"2029.06","title":{"zhCN":"答辩、毕业与 Cyber 系列项目最终归档","en":"Thesis defense, graduation, and final archiving of the Cyber projects"}}]}'::jsonb, 'records', '{}'::jsonb), 'tech-v3-migration');
  ELSIF current_payload->>'version' = '2' THEN
    IF jsonb_typeof(current_payload->'records') IS DISTINCT FROM 'object' THEN
      RAISE EXCEPTION 'Invalid V2 Tech records';
    END IF;
    FOR old_key IN SELECT jsonb_object_keys(current_payload->'records') LOOP
      IF NOT id_map ? old_key THEN
        RAISE EXCEPTION 'Unknown V2 Tech record key: %', old_key;
      END IF;
      migrated_records := migrated_records || jsonb_build_object(id_map->>old_key, current_payload->'records'->old_key);
    END LOOP;
    UPDATE app.owner_managed_datasets
      SET payload = jsonb_build_object('version', 3, 'roadmap', '{"stages":[{"allocation":{"motion":5,"research":25,"robot":70},"date":"2026.09—2027.01","focus":{"zhCN":"以课程为主，先打牢现代 C++、Linux、STM32 和 ROS 2 硬件接入链路；暂时不追机械臂实机、VLA、3DGS 等高级功能","en":"Prioritize coursework and establish modern C++, Linux, STM32, and ROS 2 hardware integration foundations. Defer physical-arm deployment, VLA, 3DGS, and other advanced features."},"id":"c3ed611b-6b9c-462a-b2ae-ac03f32b33c1","milestone":{"zhCN":"Cyber AMR v0.5：STM32 → C++ Driver → ros2_control 完整打通","en":"Cyber AMR v0.5: complete STM32 → C++ Driver → ros2_control integration"},"position":0,"tasks":[{"goal":{"zhCN":"为后续所有机器人模块建立统一、可维护、可测试的工程规范。","en":"Establish consistent, maintainable, testable engineering practices for all subsequent robotics modules."},"id":"842ed1fc-57aa-4237-9a64-c5cbb3b7e658","position":0,"stack":["C++23","CMake","Linux","Git","GoogleTest","GDB"],"subtasks":[{"acceptance":{"zhCN":"","en":""},"id":"21170054-2879-4582-825b-e9b8c9ef5a76","position":0,"title":{"zhCN":"掌握 RAII、智能指针、移动语义、常用 STL 与错误处理","en":"Master RAII, smart pointers, move semantics, common STL facilities, and error handling"}},{"acceptance":{"zhCN":"","en":""},"id":"c31409a4-1e22-4ee2-a00a-f1ee8c6c4d38","position":1,"title":{"zhCN":"掌握线程、mutex、condition_variable、atomic 与常见并发问题","en":"Master threads, mutex, condition_variable, atomic, and common concurrency issues"}},{"acceptance":{"zhCN":"","en":""},"id":"a02c8ccc-d3d8-41c0-8511-9d25bca3326d","position":2,"title":{"zhCN":"掌握 target、库组织、依赖传递、install / export 与 find_package","en":"Master targets, library organization, transitive dependencies, install / export, and find_package"}},{"acceptance":{"zhCN":"","en":""},"id":"e0e84901-bd16-4ff7-b593-79bb0a68f069","position":3,"title":{"zhCN":"使用 GoogleTest 建立单元测试，并接入基础 CI","en":"Build GoogleTest unit tests and connect them to basic CI"}},{"acceptance":{"zhCN":"","en":""},"id":"02789ace-567d-4956-90d0-371682a491ab","position":4,"title":{"zhCN":"使用 GDB、S